INSERT INTO screening_question_templates (title, questions, is_active) VALUES
('Opening / Rapport', '[{"question": "Tell me a little about yourself and what drew you to caregiving.", "category": "General"}, {"question": "What types of clients have you worked with most — elderly, post-surgical, dementia, pediatric?", "category": "General"}]'::jsonb, true),
('Clinical Competency', '[{"question": "Walk me through how you''d handle a client who refuses their medication.", "category": "Clinical Competency"}, {"question": "Have you managed wound care, catheter care, or feeding tubes? Which are you most comfortable with?", "category": "Clinical Competency"}, {"question": "How do you handle a medical emergency — say a client falls or shows signs of a stroke?", "category": "Clinical Competency"}]'::jsonb, true),
('Team / Rotation Fit', '[{"question": "At Tavara, we rotate caregivers in a household so clients aren''t dependent on one person. How do you feel about sharing a client with other nurses?", "category": "Team & Rotation Fit"}, {"question": "How do you handle handoff — what information do you pass to the next caregiver coming on shift?", "category": "Team & Rotation Fit"}, {"question": "Have you ever worked in a team-based care setting before? What worked well and what didn''t?", "category": "Team & Rotation Fit"}]'::jsonb, true),
('Reliability, Culture & Red-Flag Checks', '[{"question": "What does your ideal schedule look like — days, evenings, weekends, overnights?", "category": "Reliability & Professionalism"}, {"question": "How do you handle last-minute shift requests or schedule changes?", "category": "Reliability & Professionalism"}, {"question": "Have you ever had a conflict with a client''s family member? How did you resolve it?", "category": "Reliability & Professionalism"}, {"question": "Some of our families have specific cultural or dietary preferences. How do you adapt to different household routines?", "category": "General"}, {"question": "Are you comfortable working in different areas — San Fernando, Chaguanas, Port of Spain — or do you have a preferred zone?", "category": "General"}, {"question": "Why did you leave your last caregiving position?", "category": "Red-Flag Checks"}, {"question": "Can you provide two professional references we can contact?", "category": "Red-Flag Checks"}, {"question": "Is there anything about how we operate — team rotations, documentation requirements, family communication — that concerns you?", "category": "Red-Flag Checks"}]'::jsonb, true);